<?php
require_once 'includes/config.php'; require_once 'includes/phase1.php';
$roll=trim($_GET['rollid']??$_POST['rollid']??'');$class=(int)($_GET['class']??$_POST['class']??0);$year=trim($_GET['academic_year']??$_POST['academic_year']??'');$term=trim($_GET['term']??$_POST['term']??'Final');$exam=trim($_GET['exam_type']??$_POST['exam_type']??'');$student=null;$rows=[];$total=0;$out=0;
if($roll&&$class&&$year&&$term&&$exam){$q=$dbh->prepare('SELECT s.*,c.ClassName,c.Section FROM tblstudents s JOIN tblclasses c ON c.id=s.ClassId WHERE s.RollId=:r AND s.ClassId=:c LIMIT 1');$q->execute([':r'=>$roll,':c'=>$class]);$student=$q->fetch();if($student){$q=$dbh->prepare("SELECT sub.SubjectName,r.marks,r.MaxMarks FROM tblresult r JOIN tblsubjects sub ON sub.id=r.SubjectId WHERE r.StudentId=:s AND r.ClassId=:c AND r.AcademicYear=:y AND r.Term=:t AND r.ExamType=:e AND r.Published=1 AND r.approval_state='approved' AND r.result_status='approved' ORDER BY sub.SubjectName");$q->execute([':s'=>$student['StudentId'],':c'=>$class,':y'=>$year,':t'=>$term,':e'=>$exam]);$rows=$q->fetchAll();foreach($rows as $r){$total+=(int)$r['marks'];$out+=(int)$r['MaxMarks'];}}}
$pct=$out?($total/$out)*100:0;[$grade,$remark]=grade_for($pct);$classPosition=null;$classCount=0;if($student&&$rows){$rankQ=$dbh->prepare("SELECT StudentId,(SUM(marks)/NULLIF(SUM(MaxMarks),0))*100 AS pct FROM tblresult WHERE ClassId=:c AND AcademicYear=:y AND Term=:t AND ExamType=:e AND Published=1 AND approval_state='approved' AND result_status='approved' GROUP BY StudentId ORDER BY pct DESC,StudentId ASC");$rankQ->execute([':c'=>$class,':y'=>$year,':t'=>$term,':e'=>$exam]);$rank=0;foreach($rankQ->fetchAll() as $rr){$rank++;$classCount++;if((int)$rr['StudentId']===(int)$student['StudentId'])$classPosition=$rank;}}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Report Card | SRMS</title><link rel="stylesheet" href="css/bootstrap.min.css"><link rel="stylesheet" href="css/font-awesome.min.css"><style>@media print{.no-print{display:none!important}body{background:#fff}.report{box-shadow:none!important;border:0!important}}body{background:#f4f6f8}.report{max-width:900px;margin:25px auto;background:#fff;border:1px solid #ddd;padding:30px;box-shadow:0 2px 10px rgba(0,0,0,.08)}.school-title{text-align:center;border-bottom:3px solid #333;padding-bottom:15px;margin-bottom:20px}.summary td{padding:8px}.signature{margin-top:70px}</style><link rel="stylesheet" href="css/srms-responsive.css" media="screen">
</head><body><div class="report"><div class="school-title"><h2><?php echo e(APP_NAME);?></h2><h3>OFFICIAL STUDENT REPORT CARD</h3><p><?php echo e($year.' · '.$term.' · '.$exam);?></p></div><?php if(!$student):?><div class="alert alert-warning">Enter a valid published result to view the report card.</div><?php elseif(!$rows):?><div class="alert alert-warning">No published result is available for this period.</div><?php else:?><table class="table table-bordered summary"><tr><td><strong>Student Name</strong></td><td><?php echo e($student['StudentName']);?></td><td><strong>Roll ID</strong></td><td><?php echo e($student['RollId']);?></td></tr><tr><td><strong>Class</strong></td><td><?php echo e($student['ClassName'].' '.$student['Section']);?></td><td><strong>Date</strong></td><td><?php echo date('d M Y');?></td></tr></table><table class="table table-bordered"><thead><tr><th>#</th><th>Subject</th><th>Marks</th><th>Percentage</th><th>Grade</th></tr></thead><tbody><?php foreach($rows as $i=>$r):$sp=((int)$r['marks']/(int)$r['MaxMarks'])*100;[$g,$gr]=grade_for($sp);?><tr><td><?php echo $i+1;?></td><td><?php echo e($r['SubjectName']);?></td><td><?php echo (int)$r['marks'].' / '.(int)$r['MaxMarks'];?></td><td><?php echo number_format($sp,1);?>%</td><td><strong><?php echo e($g);?></strong></td></tr><?php endforeach;?><tr><th colspan="2">TOTAL</th><th><?php echo $total.' / '.$out;?></th><th><?php echo number_format($pct,2);?>%</th><th><?php echo e($grade);?></th></tr></tbody></table><div class="alert alert-info"><strong>Overall Performance:</strong> <?php echo e($remark);?><?php if($classPosition!==null):?> &nbsp; <strong>Class Position:</strong> <?php echo (int)$classPosition;?> of <?php echo (int)$classCount;?><?php endif;?></div><div class="row signature"><div class="col-xs-4 text-center">____________________<br>Class Teacher</div><div class="col-xs-4 text-center">____________________<br>Head of Department</div><div class="col-xs-4 text-center">____________________<br>Principal</div></div><?php endif;?><div class="no-print" style="margin-top:30px"><button onclick="window.print()" class="btn btn-primary">Print Report Card</button><a href="find-result.php" class="btn btn-default">Back to Results</a></div></div></body></html>
